  const wait = ms => new Promise(r => setTimeout(r, ms));
  await wait(900);
  const opt = id => document.querySelector(`.opt[data-id="${id}"]`);
  document.querySelector('#hintBtn').click(); document.querySelector('#hintBtn').click();
  opt('ovo').click(); opt('ovo').click();          // segundo clique durante bloqueio não conta
  await wait(500);
  opt('ovo').click(); await wait(500);
  const r1 = document.querySelector('#debug').innerText;
  opt('dino').click(); opt('dino').click();         // clique duplo no acerto
  await wait(1200);
  const r2 = document.querySelector('#debug').innerText;
  document.querySelector('#exit').click();           // já concluído: sai sem abandonar
  const r3 = document.querySelector('#debug').innerText;
  return { r1, r2, r3, left: !document.querySelector('#s-left').hidden };
}

