async (page) => {
  const dir = 'C:/Users/migue/Documents/hackathon-dopamine-worktrees/miguel-sequencia/docs/sequencia/implementacao/';
  const dbg = () => page.evaluate(() => window.sequenceDebug());
  const results = () => page.evaluate(() => document.getElementById('seq-debug').textContent.trim().split('\n').filter(Boolean).map(JSON.parse));
  const ready = () => page.waitForFunction(() => document.getElementById('seq-loading').hidden && window.sequenceDebug?.().layout, null, { timeout: 15000 });
  const report = {};
  for (const [name, w, h] of [['celular', 390, 844], ['celular-deitado', 844, 390], ['tablet-retrato', 820, 1180], ['tablet-deitado', 1180, 820]]) {
    await page.setViewportSize({ width: w, height: h });
    await page.goto('http://127.0.0.1:5175/sequencia.html?debug=1');
    await ready(); await page.waitForTimeout(200);
    await page.screenshot({ path: dir + `${name}-1-atividade.png` });
    let d = await dbg();
    const L = d.layout;
    const opt = id => L.options[d.options.indexOf(id)];
    const wrong = opt(d.options.find(id => id !== d.answer)), right = opt(d.answer);
    await page.mouse.click(L.hintBtn.x + 50, L.hintBtn.y + 24);
    await page.mouse.click(L.hintBtn.x + 50, L.hintBtn.y + 24);
    await page.mouse.dblclick(wrong.x, wrong.y);           // clique duplo no errado
    await page.waitForTimeout(450);
    await page.screenshot({ path: dir + `${name}-2-dica-erro.png` });
    const afterWrong = (await dbg()).metrics;
    await page.mouse.dblclick(right.x, right.y);           // clique duplo no certo
    await page.waitForTimeout(1300);
    await page.screenshot({ path: dir + `${name}-3-concluido.png` });
    d = await dbg();
    const res = await results();
    const again = d.layout.end[0];
    await page.mouse.click(again.x + again.w / 2, again.y + again.h / 2);
    await ready(); await page.waitForTimeout(200);
    const replay = (await dbg()).metrics;
    await page.click('#seq-exit');
    const dialogOpen = await page.isVisible('#seq-confirm');
    await page.click('#seq-leave');
    const res2 = await results();
    const scroll = await page.evaluate(() => document.documentElement.scrollHeight > innerHeight || document.documentElement.scrollWidth > innerWidth);
    report[name] = { afterWrong, finalMetrics: d.metrics, results: res.map(r => `${r.status} a${r.attempts} c${r.correct} h${r.hints}`), replay, dialogOpen, afterExit: res2.slice(1).map(r => `${r.status} a${r.attempts}`), sameIdOnReplay: res2[0].activityId === res2[1]?.activityId, scroll };
  }
  return report;
}

