async (page) => {
  const dir = 'C:/Users/migue/Documents/hackathon-dopamine-worktrees/miguel-sequencia/docs/sequencia/implementacao/';
  const dbg = () => page.evaluate(() => window.sequenceDebug());
  const results = () => page.evaluate(() => document.getElementById('seq-debug').textContent.trim().split('\n').filter(Boolean).map(JSON.parse).map(r => r.status));
  const ready = () => page.waitForFunction(() => document.getElementById('seq-loading').hidden && document.getElementById('seq-error').hidden && window.sequenceDebug?.().layout, null, { timeout: 15000 });
  const out = {};
  await page.setViewportSize({ width: 390, height: 844 });
  // 1. Falha de imagem → Tentar de novo
  await page.goto('http://127.0.0.1:5175/sequencia.html?debug=1&falha=1');
  await page.waitForSelector('#seq-error:not([hidden])', { timeout: 15000 });
  await page.screenshot({ path: dir + 'celular-falha-imagem.png' });
  await page.click('#seq-retry'); await ready();
  out.retryRecovered = (await dbg()).layout !== undefined;
  // 1b. Falha → Voltar = abandono
  await page.goto('http://127.0.0.1:5175/sequencia.html?debug=1&falha=1');
  await page.waitForSelector('#seq-error:not([hidden])');
  await page.click('#seq-back');
  out.backFromError = await results();
  // 2. Movimento reduzido + tema trem: acerto sem voo
  await page.goto('http://127.0.0.1:5175/sequencia.html?debug=1&rm=1&tema=trem');
  await ready();
  let d = await dbg();
  let right = d.layout.options[d.options.indexOf(d.answer)];
  await page.mouse.click(right.x, right.y);
  await page.waitForTimeout(60);
  out.reducedMotionImmediate = (await dbg()).session.solved;
  await page.waitForTimeout(900);
  await page.screenshot({ path: dir + 'celular-trem-concluido.png' });
  // 3. Giro de tela no meio do voo do acerto
  await page.goto('http://127.0.0.1:5175/sequencia.html?debug=1');
  await ready();
  d = await dbg();
  right = d.layout.options[d.options.indexOf(d.answer)];
  await page.mouse.click(right.x, right.y);
  await page.waitForTimeout(80);
  await page.setViewportSize({ width: 844, height: 390 });
  await page.waitForTimeout(1300);
  d = await dbg();
  out.rotateMidFlight = { mode: d.layout.mode, results: await results() };
  await page.screenshot({ path: dir + 'celular-giro-apos-acerto.png' });
  // 4. Diálogo de saída: Continuar mantém o jogo
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto('http://127.0.0.1:5175/sequencia.html?debug=1');
  await ready();
  await page.click('#seq-exit');
  await page.screenshot({ path: dir + 'celular-confirmar-saida.png' });
  await page.click('#seq-stay');
  out.stayKeepsGame = { dialog: await page.isVisible('#seq-confirm'), results: await results() };
  // 5. Reentrada depois de sair
  await page.click('#seq-exit'); await page.click('#seq-leave');
  await page.click('#seq-reenter'); await ready();
  out.reentry = (await dbg()).metrics;
  out.canvasCount = await page.evaluate(() => document.querySelectorAll('canvas').length);
  return out;
}

