  const wrong = d.layout.options[d.options.indexOf(d.options.find(i => i !== d.answer))];
  const right = d.layout.options[d.options.indexOf(d.answer)];
  await p.touchscreen.tap(wrong.x, wrong.y);
  await p.waitForTimeout(450);
  await p.touchscreen.tap(right.x, right.y);
  await p.touchscreen.tap(right.x, right.y);
  await p.waitForTimeout(1200);
  d = await p.evaluate(() => window.sequenceDebug());
  const canvas = await p.evaluate(() => { const c = document.querySelector('canvas'); return [c.width, c.height, c.style.width]; });
