    if (this.showEnd) {
      const [again, exit] = L.end;
      this.ui.add(this.button(again, 'Jogar de novo', () => this.replay(), { primary: true }));
      this.ui.add(this.button(exit, 'Sair', () => this.game.events.emit(EXIT_EVENT)));
      return;
    }
